from renderer import SecurityError, render

class User:
    def __init__(self, name):
        self.name = name
        self._secret = 'topsecret'

class TestTemplateSandbox(unittest.TestCase):
    def test_lookup_index_and_filters(self):
        ctx = {'user': User('  alice  '), 'items': ['zero', 'one']}
        out = render('Hi {{ user.name | strip | upper }}: {{ items[1] }}', ctx)
        self.assertEqual(out, 'Hi ALICE: one')

    def test_blocks_dunder_and_private_access(self):
        ctx = {'user': User('bob'), 'data': {'_secret': 'x'}}
        with self.assertRaises(SecurityError):
            render('{{ user.__class__.__mro__ }}', ctx)
        with self.assertRaises(SecurityError):
            render('{{ user._secret }}', ctx)
        with self.assertRaises(SecurityError):
            render('{{ data._secret }}', ctx)

    def test_escaped_braces_and_missing_key(self):
        self.assertEqual(render(r'Literal \{{ user.name }}', {'user': {'name': 'x'}}), 'Literal {{ user.name }}')
        with self.assertRaises(KeyError):
            render('{{ missing.field }}', {})

if __name__ == '__main__':
    unittest.main()

