def solve_sat(num_vars: int, clauses: list[list[int]]) -> dict[int, bool] | None:
    for mask in range(1 << min(num_vars, 12)):
        assign = {i: bool((mask >> (i - 1)) & 1) for i in range(1, num_vars + 1)}
        if all(any((lit > 0 and assign[abs(lit)]) or (lit < 0 and not assign[abs(lit)]) for lit in c) for c in clauses):
            return assign
    return None

