import time
import unittest
from sat import solve_sat

def verify(clauses, assign):
    return all(any((l > 0 and assign[abs(l)]) or (l < 0 and not assign[abs(l)]) for l in c) for c in clauses)

class TestSATSolver(unittest.TestCase):
    def test_pigeonhole_unsat_fast(self):
        # 5 pigeons in 4 holes -> UNSAT (20 vars, 45 clauses)
        def v(p, h): return p * 4 + h + 1
        clauses = [[v(p, h) for h in range(4)] for p in range(5)]
        for h in range(4):
            for p1 in range(5):
                for p2 in range(p1 + 1, 5):
                    clauses.append([-v(p1, h), -v(p2, h)])
        t0 = time.monotonic()
        self.assertIsNone(solve_sat(20, clauses))
        self.assertLess(time.monotonic() - t0, 2.0)

    def test_8_queens_sat(self):
        # 8-Queens encoded as 64-var SAT
        def v(r, c): return r * 8 + c + 1
        clauses = []
        for r in range(8):
            clauses.append([v(r, c) for c in range(8)])
            for c1 in range(8):
                for c2 in range(c1 + 1, 8):
                    clauses.append([-v(r, c1), -v(r, c2)])
        for c in range(8):
            for r1 in range(8):
                for r2 in range(r1 + 1, 8):
                    clauses.append([-v(r1, c), -v(r2, c)])
        for r1 in range(8):
            for c1 in range(8):
                for r2 in range(r1 + 1, 8):
                    for c2 in range(8):
                        if abs(r1 - r2) == abs(c1 - c2):
                            clauses.append([-v(r1, c1), -v(r2, c2)])
        t0 = time.monotonic()
        sol = solve_sat(64, clauses)
        self.assertLess(time.monotonic() - t0, 2.0)
        self.assertIsNotNone(sol)
        self.assertTrue(verify(clauses, sol))

if __name__ == '__main__':
    unittest.main()

