def plan_routes(orders: list[dict], vehicles: list[dict], depot: tuple[float, float]) -> dict[str, list[str]]:
    routes = {v['id']: [] for v in vehicles}
    loads = {v['id']: 0.0 for v in vehicles}
    for o in orders:
        for v in vehicles:
            if loads[v['id']] + o['weight'] <= v['capacity']:
                routes[v['id']].append(o['id'])
                loads[v['id']] += o['weight']
                break
    return routes

